  var стили = ["\n  :root {\n    --ink: #000000;\n    --muted: #5f6368;\n    --line: #dadce0;\n    --field-bg: #f1f5f9;\n    --field-line: #1c74e9;\n    --accent: #1a73e8;\n    --result-bg: #d6e6fc;\n  }\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body {\n    font-family: 'Google Sans', 'Product Sans', Roboto, Arial, sans-serif;\n    color: var(--ink);\n    background: #ffffff;\n    line-height: 1.65;\n    -webkit-font-smoothing: antialiased;\n  }\n  h1, h2, h3 { overflow-wrap: break-word; }\n  .page {\n    max-width: 720px;\n    margin: 0 auto;\n    padding: 56px 24px 96px;\n    counter-reset: rownum;\n  }\n  .field-row, .info-row, .mini-result {\n    position: relative;\n    counter-increment: rownum;\n  }\n  .field-row::before, .info-row::before, .mini-result::before {\n    content: counter(rownum);\n    position: absolute;\n    top: 3px;\n    right: 8px;\n    font-size: 10px;\n    font-weight: 700;\n    color: var(--muted);\n    opacity: 0.5;\n    line-height: 1;\n  }\n  .brand {\n    font-size: 15px;\n    font-weight: 700;\n    letter-spacing: 0.02em;\n    margin-bottom: 6px;\n  }\n  .brand span { font-weight: 400; color: var(--muted); }\n  h1 {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    font-size: 34px;\n    font-weight: 700;\n    line-height: 1.2;\n    margin: 18px 0 10px;\n    letter-spacing: -0.01em;\n  }\n  .h1-light { font-weight: 400; }\n  .lead {\n    font-size: 17px;\n    color: var(--muted);\n    margin-bottom: 44px;\n  }\n  .step {\n    margin-bottom: 40px;\n    border: 1px solid var(--line);\n    border-radius: 14px;\n    padding: 26px 26px 24px;\n  }\n  .step-head {\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    margin-bottom: 18px;\n  }\n  .step-num {\n    font-family: 'Roboto Mono', monospace;\n    font-size: 20px;\n    font-weight: 500;\n    color: var(--accent);\n    background: transparent;\n    border: 1px solid var(--accent);\n    border-radius: 9px;\n    width: 36px;\n    height: 36px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .step h2 {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    font-size: 22px;\n    font-weight: 700;\n    letter-spacing: -0.01em;\n    color: var(--accent);\n    text-wrap: balance;\n  }\n  .step p {\n    font-size: 17px;\n    margin-bottom: 9.2px;\n  }\n  .substep {\n    margin-top: 18px;\n    border: 1px solid var(--ink);\n    border-radius: 10px;\n    padding: 18px 18px 16px;\n  }\n  .substep:first-of-type {\n    margin-top: 0;\n  }\n  .substep-head {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin-bottom: 12px;\n  }\n  .substep-num {\n    font-size: 13px;\n    font-weight: 600;\n    letter-spacing: 0;\n    color: var(--ink);\n    background: transparent;\n    border: 1px solid var(--ink);\n    border-radius: 7px;\n    min-width: 26px;\n    height: 26px;\n    padding: 0 8px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .substep h3 {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    font-size: 17px;\n    font-weight: 700;\n    color: var(--ink);\n    margin-bottom: 0;\n  }\n  /* Строки-действия: поле (редактируемое) и факт (нередактируемый) — общая сетка с плашками результатов */\n  .field-row, .info-row {\n    display: grid;\n    grid-template-columns: 1fr 200px;\n    column-gap: 16px;\n    align-items: center;\n    background: #ffffff;\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    padding: 12px 16px;\n    margin-top: 11.5px;\n  }\n  /* строки внутри подблока: не прилипают к его рамке, колонка цифр остаётся на общей вертикали */\n  .substep .field-row, .substep .info-row {\n    grid-template-columns: 1fr 182px;\n  }\n  .field-row + .field-row, .field-row + .info-row,\n  .info-row + .info-row, .info-row + .field-row,\n  .mini-result + .field-row, .mini-result + .info-row,\n  .field-row + .mini-result, .info-row + .mini-result {\n    margin-top: 9.2px;\n  }\n  .field-row .row-label, .info-row .row-label {\n    grid-column: 1;\n    grid-row: 1;\n    display: block;\n    font-size: 15.5px;\n    font-weight: 500;\n    line-height: 1.2;\n    color: var(--ink);\n  }\n  .row-note {\n    grid-column: 1;\n    grid-row: 2;\n    display: block;\n    font-size: 14px;\n    line-height: 1.2;\n    font-style: italic;\n    color: var(--muted);\n    margin-top: 2px;\n  }\n  .field-value {\n    grid-column: 2;\n    grid-row: 1 / 3;\n    display: flex;\n    flex-direction: column;\n    align-items: flex-start;\n  }\n  .fld {\n    appearance: none;\n    -webkit-appearance: none;\n    -moz-appearance: none;\n    font: inherit;\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n    font-size: 26px;\n    line-height: 1.2;\n    color: var(--ink);\n    background: var(--field-bg);\n    border: none;\n    border-radius: 8px;\n    padding: 0 10px;\n    margin-left: 15.6px;\n    text-align: left;\n    field-sizing: content;\n    min-width: 2ch;\n    max-width: 190px;\n    outline: none;\n    -moz-appearance: textfield;\n  }\n  .fld::-webkit-outer-spin-button, .fld::-webkit-inner-spin-button { -webkit-appearance: none; }\n  .fld:focus { background: #e8f0fe; }\n  .field-unit {\n    display: block;\n    font-size: 13px;\n    font-weight: 700;\n    line-height: 1.2;\n    color: var(--ink);\n    margin-top: 2px;\n    padding: 0 10px;\n    margin-left: 15.6px;\n  }\n  /* пара значений «до / после» в одной строке: левое редактируемое, правое — характеристика МС.\n     Каждое значение со своей единицей, единица выровнена по левому краю своего числа. */\n  .pair {\n    display: flex;\n    align-items: flex-start;\n    gap: 2px;\n  }\n  .pair-item {\n    display: flex;\n    flex-direction: column;\n    align-items: flex-start;\n  }\n  .pair-item:first-child { margin-left: 15.6px; }\n  .pair .fld { margin-left: 0; }\n  .pair .field-unit { margin-left: 0; }\n  .pair-sep, .pair-fixed {\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n    font-size: 26px;\n    line-height: 1.2;\n    color: var(--ink);\n  }\n  .pair-fixed { padding: 0 10px; }\n  .pair-sep { color: var(--muted); font-weight: 400; padding-left: 6px; }\n  .info-num {\n    display: block;\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n    font-size: 26px;\n    line-height: 1.2;\n    color: var(--ink);\n    padding: 0 10px;\n    margin-left: 15.6px;\n  }\n  /* Узкий экран: подпись, пояснение и значение идут друг под другом,\n     а не в двух колонках — иначе значение ложится поверх подписи. */\n  @media (max-width: 560px) {\n    .field-row, .info-row {\n      grid-template-columns: 1fr;\n    }\n    .substep .field-row, .substep .info-row {\n      grid-template-columns: 1fr;\n    }\n    .field-row .row-label, .info-row .row-label { grid-row: 1; }\n    .row-note { grid-row: 2; }\n    .field-value {\n      grid-column: 1;\n      grid-row: 3;\n      margin-top: 8px;\n    }\n    .step h2, .total h2, .substep h3 { overflow-wrap: break-word; min-width: 0; }\n    .step h2 { font-size: 19px; }\n    .total h2 { font-size: 17px; letter-spacing: 0; }\n    .total { padding: 20px 16px; }\n    /* номер блока встаёт над заголовком: заголовку вся ширина,\n       а левый край общий со строками ниже */\n    .step-head, .climax-head, .substep-head {\n      flex-direction: column;\n      align-items: flex-start;\n      gap: 8px;\n    }\n    .step-num, .climax-badge {\n      width: 30px;\n      height: 30px;\n      font-size: 16px;\n      border-radius: 8px;\n    }\n    .substep h3 { font-size: 15px; }\n    .step { padding: 18px 16px 16px; }\n    /* на узком экране подблок не сдвигает свои строки вправо:\n       рамка убрана, отступы по бокам нулевые — левый край общий со всеми */\n    .substep { padding: 14px 0 0; border: none; }\n    .substep .field-row, .substep .info-row { padding: 12px 16px; }\n    .fld, .pair-sep, .pair-fixed, .info-num { font-size: 22px; }\n    .fld, .field-unit, .info-num { margin-left: 0; }\n    .pair-item:first-child { margin-left: 0; }\n    .field-unit { padding-left: 10px; }\n  }\n  .mini-result {\n    display: grid;\n    grid-template-columns: 1fr 200px;\n    column-gap: 16px;\n    align-items: center;\n    background: var(--result-bg);\n    border-top: 1px solid transparent;\n    border-bottom: 1px solid transparent;\n    border-left: 3px solid var(--accent);\n    border-radius: 0 8px 8px 0;\n    padding: 12px 16px;\n    margin-top: 11.5px;\n    font-size: 14px;\n    font-variant-numeric: tabular-nums;\n  }\n  .mini-result + .mini-result { margin-top: 9.2px; }\n  /* постоянная часть эффекта — не зависит от вводимых допущений, отмечена серым;\n     переменная остаётся голубой */\n  .mini-result.const {\n    background: #e8eaed;\n    border-left-color: #80868b;\n  }\n  /* промежуточные действия — светлее, чем строки-итоги эффекта */\n  .mini-result.interim {\n    background: #edf4fe;\n    border-left-color: #a8c7f0;\n  }\n  .mini-result .label {\n    grid-column: 1;\n    grid-row: 1;\n    display: block;\n    color: var(--ink);\n    font-weight: 500;\n    margin-bottom: 2px;\n    font-size: 15.5px;\n    line-height: 1.2;\n  }\n  .mini-result .formula {\n    grid-column: 1;\n    grid-row: 2;\n    color: var(--muted);\n    font-size: 14px;\n    line-height: 1.2;\n  }\n  .mini-result .num {\n    grid-column: 2;\n    grid-row: 1 / 3;\n    text-align: left;\n    line-height: 1.2;\n    padding: 0 10px;\n    margin-left: 15.6px;\n  }\n  .mini-result .num .num-value {\n    display: block;\n    font-size: 26px;\n    font-weight: 700;\n    color: var(--ink);\n  }\n  .mini-result .num .num-unit {\n    display: block;\n    font-size: 13px;\n    font-weight: 700;\n    color: var(--ink);\n    margin-top: 2px;\n  }\n  @media (max-width: 560px) {\n    .mini-result {\n      grid-template-columns: 1fr;\n    }\n    /* левый край общий со строками: рамка слева 3 точки вместо 1,\n       поэтому отступ на 2 меньше, а у числа свои отступы сняты */\n    .mini-result { padding-left: 14px; }\n    .mini-result .num {\n      grid-column: 1;\n      grid-row: 3;\n      margin-top: 6px;\n      margin-left: 0;\n      padding: 0;\n      font-size: 22px;\n    }\n  }\n  p.anno {\n    font-size: 14px;\n    font-style: italic;\n    color: var(--muted);\n    margin-top: 4px;\n  }\n  .tariff-wrap {\n    overflow-x: auto;\n    margin-top: 10px;\n    border: 1px solid var(--line);\n    border-radius: 10px;\n  }\n  .tariff-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 14px;\n  }\n  .tariff-table th, .tariff-table td {\n    padding: 10px 12px;\n    text-align: center;\n    vertical-align: middle;\n    border-bottom: 1px solid var(--line);\n    white-space: nowrap;\n  }\n  .tariff-table tbody tr {\n    height: 64px;\n  }\n  .tariff-table .tariff-feature-col {\n    text-align: left;\n    white-space: normal;\n    font-weight: 400;\n    color: var(--ink);\n    width: 46%;\n  }\n  .tariff-table thead th {\n    background: var(--field-bg);\n    font-weight: 700;\n    vertical-align: top;\n  }\n  .tariff-table thead th.tariff-feature-col {\n    vertical-align: middle;\n  }\n  .tariff-table thead label {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 4px;\n    cursor: pointer;\n  }\n  .tariff-sub {\n    font-weight: 400;\n    color: var(--muted);\n    font-size: 12px;\n  }\n  .tariff-table tbody td:not(.tariff-feature-col) {\n    color: var(--accent);\n    font-weight: 700;\n  }\n  .tariff-price-row td {\n    background: var(--result-bg);\n    font-weight: 700;\n    font-variant-numeric: tabular-nums;\n    border-bottom: none;\n  }\n  .tariff-price-row .tariff-feature-col {\n    font-weight: 700;\n    font-size: 15.1px;\n  }\n  .tariff-price-row:first-of-type td {\n    border-bottom: 1px solid var(--line);\n  }\n  /* цифры тарифной таблицы — в стиле строк: крупное число, размерность мелко под ним */\n  .tariff-num {\n    display: block;\n    font-size: 21.6px;\n    font-weight: 700;\n    line-height: 1.2;\n    color: var(--ink);\n  }\n  .tariff-num-unit {\n    display: block;\n    font-size: 11.9px;\n    font-weight: 700;\n    line-height: 1.2;\n    color: var(--ink);\n    margin-top: 2px;\n  }\n  /* Итоговые блоки — песочный фон, единый с блоками выводов в ms-benefits-RF.html */\n  .total {\n    margin-top: 56px;\n    margin-bottom: 56px;\n    /* боковые поля те же, что у обычных блоков, чтобы содержимое всех блоков\n       начиналось на одном левом крае */\n    padding: 32px 26px;\n    background: #f4ecd8;\n    color: #3a2f1f;\n    border: 1px solid #e0d3ae;\n    border-radius: 16px;\n  }\n  .total h2 {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    font-size: 24px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.02em;\n    color: #3a2f1f;\n    margin-bottom: 14px;\n  }\n  .climax-head {\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    margin-bottom: 14px;\n  }\n  .climax-head h2 {\n    margin-bottom: 0;\n  }\n  .climax-badge {\n    font-family: 'Roboto Mono', monospace;\n    font-size: 20px;\n    font-weight: 500;\n    color: #000;\n    background: transparent;\n    border: 1px solid #000;\n    border-radius: 9px;\n    width: 36px;\n    height: 36px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .total .grand {\n    font-size: 40px;\n    font-weight: 700;\n    line-height: 1.15;\n    letter-spacing: -0.01em;\n    font-variant-numeric: tabular-nums;\n  }\n  .total .grand .grand-sub {\n    font-size: 20px;\n  }\n  /* Совокупный эффект: число стоит в чёрном прямоугольнике со скруглением,\n     левым краем прямоугольник встаёт на общий край блока. */\n  #grandTotal, #paybackGrand {\n    display: inline-block;\n    background: #000;\n    color: #f4ecd8;\n    border-radius: 12px;\n    padding: 6px 14px;\n  }\n  .total .plus {\n    margin-top: 14px;\n    font-size: 17px;\n    color: #7a6a50;\n    line-height: 1.6;\n  }\n  .total .plus b { color: inherit; }\n  .total.climax {\n    background: #f4ecd8;\n    padding: 44px 26px;\n    box-shadow: 0 16px 40px rgba(58, 47, 31, 0.18);\n  }\n  .climax-num {\n    font-size: 56px;\n  }\n  .climax-formula {\n    font-size: 17px;\n    color: #7a6a50;\n    line-height: 1.6;\n    margin-bottom: 10px;\n  }\n  .climax-formula div { margin-bottom: 4px; }\n  .climax-formula b { color: inherit; }\n  .climax-tagline {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    margin-top: 18px;\n    font-size: 17px;\n    font-weight: 700;\n    color: #3a2f1f;\n  }\n  @media (max-width: 480px) {\n    .climax-num { font-size: 40px; }\n  }\n  .foot {\n    margin-top: 28px;\n    font-size: 13px;\n    color: var(--muted);\n    line-height: 1.6;\n  }\n  @media (max-width: 480px) {\n    h1 { font-size: 27px; }\n    .total .grand { font-size: 31px; }\n  }\n\n  .toc {\n    margin: 0 0 44px;\n    border: 1px solid var(--line);\n    border-radius: 14px;\n    padding: 22px 26px 20px;\n  }\n  .toc h2 {\n    font-family: 'Unbounded', 'Google Sans', Arial, sans-serif;\n    font-size: 22px;\n    font-weight: 700;\n    letter-spacing: -0.01em;\n    margin-bottom: 12px;\n  }\n  .toc ol {\n    list-style: none;\n    padding-inline-start: 0;\n    margin-inline-start: 0;\n  }\n  .toc li { margin: 0; padding: 0; list-style: none; }\n  .toc a {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 6px 0;\n    font-size: 16px;\n    color: var(--ink);\n    text-decoration: none;\n    border-bottom: 1px solid transparent;\n  }\n  .toc a:hover { color: var(--accent); }\n  .toc .toc-num {\n    font-family: 'Roboto Mono', monospace;\n    font-size: 13px;\n    font-weight: 500;\n    color: inherit;\n    background: transparent;\n    border: 1px solid currentColor;\n    border-radius: 6px;\n    width: 24px;\n    height: 24px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n  }\n  .toc .toc-num.sand { background: #e8eaed; }\n\n  /* Пакеты на узком экране: три блока друг под другом вместо таблицы */\n  .tier-cards { display: none; }\n  @media (max-width: 560px) {\n    .tariff-wrap { display: none; }\n    .tier-cards { display: block; margin-top: 10px; }\n    .tier-card {\n      border: 1px solid var(--line);\n      border-radius: 10px;\n      padding: 14px 16px;\n      margin-top: 10px;\n    }\n    .tier-card:first-child { margin-top: 0; }\n    .tier-card.chosen { border-color: var(--accent); background: #f5f9ff; }\n    .tier-card-head {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 17px;\n      font-weight: 700;\n      cursor: pointer;\n    }\n    .tier-card-head .tier-sub {\n      font-size: 13px;\n      font-weight: 400;\n      color: var(--muted);\n    }\n    .tier-card-price {\n      display: flex;\n      justify-content: space-between;\n      align-items: baseline;\n      gap: 12px;\n      margin-top: 10px;\n      font-size: 14px;\n      color: var(--muted);\n    }\n    .tier-card-price b {\n      font-size: 20px;\n      font-weight: 700;\n      color: var(--ink);\n      font-variant-numeric: tabular-nums;\n    }\n    /* Пункты списка встают на общий левый край, без маркеров.\n       Отступ и нижний зазор задаются явно: на опубликованной странице\n       к спискам примешивается чужое правило со сдвигом вправо. */\n    .tier-card ul { list-style: none; margin: 10px 0 0; padding-left: 0; }\n    .tier-card li {\n      display: grid;\n      grid-template-columns: 12px 1fr;\n      font-size: 14px;\n      line-height: 1.35;\n      padding: 6px 0;\n    }\n    .tier-card li::before { content: '•'; }\n  }\n\n  /* Узкий экран, окончательные поправки: правила стоят после основных,\n     иначе основные их перекрывают. Номер блока встаёт над заголовком,\n     левый край заголовка совпадает с левым краем подписей в строках. */\n  @media (max-width: 560px) {\n    .step-head, .climax-head, .substep-head {\n      flex-direction: column;\n      align-items: flex-start;\n      gap: 8px;\n      padding-left: 17px;\n      margin-bottom: 10px;\n    }\n    .total, .total.climax { padding: 20px 16px; }\n    .total .grand, .total .plus, .step p,\n    .climax-formula, .climax-num, .climax-tagline { padding-left: 17px; }\n    /* содержание: пункты встают на тот же левый край, что и содержимое блоков */\n    .toc { padding-left: 33px; }\n    /* у прямоугольника с числом сдвигается сама рамка, а не текст внутри */\n    #grandTotal, #paybackGrand { margin-left: 17px; padding-left: 14px; }\n    /* На общий левый край встаёт сама рамка поля, число внутри — с отступом.\n       Ширину поля считаем сами (см. подогнатьПоле), потому что сжимать поле\n       по содержимому умеют не все браузеры. */\n    .field-unit, .info-num, .pair-fixed { padding-left: 0; padding-right: 0; }\n    .fld { padding-left: 8px; padding-right: 8px; }\n  }\n"];
